using System;
using System.Collections.Generic;
using System.Drawing;

sealed class ShapeTemplate {
 public string Id,ActionId,Name;public PointF[] Cloud;public int StrokeCount;public bool Closed,Linear;public PointF Heading;
}
sealed class ShapeCandidate {public ShapeTemplate Template;public double Score;}
static class ShapeRecognizer {
 static double Distance(PointF a,PointF b){double x=a.X-b.X,y=a.Y-b.Y;return Math.Sqrt(x*x+y*y);}
 public static ShapeTemplate Normalize(PointF[][] strokes){
  if(strokes.Length<1||strokes.Length>8)return null;double left=double.MaxValue,top=left,right=double.MinValue,bottom=right,total=0;var lengths=new double[strokes.Length];
  for(int k=0;k<strokes.Length;k++){if(strokes[k].Length<2)return null;for(int i=0;i<strokes[k].Length;i++){var p=strokes[k][i];left=Math.Min(left,p.X);right=Math.Max(right,p.X);top=Math.Min(top,p.Y);bottom=Math.Max(bottom,p.Y);if(i>0)lengths[k]+=Distance(p,strokes[k][i-1]);}total+=lengths[k];}
  double scale=Math.Max(right-left,bottom-top);if(scale<12||total<24)return null;var counts=new int[strokes.Length];int sum=0,longest=0;for(int k=0;k<counts.Length;k++){counts[k]=Math.Max(4,(int)Math.Floor(lengths[k]/total*64));sum+=counts[k];if(lengths[k]>lengths[longest])longest=k;}while(sum<64){counts[longest]++;sum++;}while(sum>64){int index=0;for(int k=1;k<counts.Length;k++)if(counts[k]>counts[index])index=k;counts[index]--;sum--;}
  var cloud=new List<PointF>();for(int k=0;k<strokes.Length;k++){var stroke=strokes[k];int cursor=1;double distance=0,step=lengths[k]/(counts[k]-1);for(int i=0;i<counts[k];i++){double target=i*step;while(cursor<stroke.Length-1&&distance+Distance(stroke[cursor],stroke[cursor-1])<target){distance+=Distance(stroke[cursor],stroke[cursor-1]);cursor++;}var a=stroke[cursor-1];var b=stroke[cursor];double segment=Distance(a,b),t=segment>0?Math.Max(0,Math.Min(1,(target-distance)/segment)):0;cloud.Add(new PointF((float)((a.X+(b.X-a.X)*t)/scale),(float)((a.Y+(b.Y-a.Y)*t)/scale)));}}
  double cx=0,cy=0;foreach(var p in cloud){cx+=p.X/64.0;cy+=p.Y/64.0;}for(int i=0;i<cloud.Count;i++)cloud[i]=new PointF((float)(cloud[i].X-cx),(float)(cloud[i].Y-cy));double hx=0,hy=0,xx=0,yy=0,xy=0;foreach(var stroke in strokes){hx+=(stroke[stroke.Length-1].X-stroke[0].X)/scale;hy+=(stroke[stroke.Length-1].Y-stroke[0].Y)/scale;}foreach(var p in cloud){xx+=p.X*p.X;yy+=p.Y*p.Y;xy+=p.X*p.Y;}bool linear=(xx+yy+Math.Sqrt((xx-yy)*(xx-yy)+4*xy*xy))/(2*Math.Max(.000001,xx+yy))>.98;return new ShapeTemplate{Cloud=cloud.ToArray(),Heading=new PointF((float)hx,(float)hy),Linear=linear,StrokeCount=strokes.Length,Closed=strokes.Length==1&&Distance(strokes[0][0],strokes[0][strokes[0].Length-1])/scale<.22};
 }
 public static List<ShapeTemplate> Compile(Dictionary<string,object> config){var list=new List<ShapeTemplate>();foreach(var item in Data.Arr(config["gestures"])){var rule=Data.Obj(item);if(!Data.B(rule,"enabled")||Data.S(rule,"kind")!="shape")continue;var strokes=new List<PointF[]>();foreach(var rawStroke in Data.Arr(rule["strokes"])){var points=new List<PointF>();foreach(var point in Data.Arr(rawStroke)){var p=Data.Obj(point);points.Add(new PointF(Convert.ToSingle(p["x"]),Convert.ToSingle(p["y"])));}strokes.Add(points.ToArray());}var shape=Normalize(strokes.ToArray());if(shape!=null){shape.Id=Data.S(rule,"id");shape.ActionId=Data.S(rule,"actionId");shape.Name=Data.S(rule,"name");list.Add(shape);}}return list;}
 static double CloudDistance(PointF[] a,PointF[] b,int start){var used=new bool[64];double sum=0;for(int n=0;n<64;n++){var p=a[(start+n)%64];int best=-1;double distance=double.MaxValue;for(int j=0;j<64;j++){if(used[j])continue;double d=Distance(p,b[j]);if(d<distance){distance=d;best=j;}}used[best]=true;sum+=(1-n/64.0)*distance;}return sum/32.5;}
 public static List<ShapeCandidate> Rank(Point[][] strokes,List<ShapeTemplate> templates){var floats=new PointF[strokes.Length][];for(int k=0;k<strokes.Length;k++){floats[k]=new PointF[strokes[k].Length];for(int i=0;i<strokes[k].Length;i++)floats[k][i]=strokes[k][i];}var result=new List<ShapeCandidate>();var input=Normalize(floats);if(input==null)return result;foreach(var t in templates){double distance=double.MaxValue;for(int start=0;start<64;start+=8)distance=Math.Min(distance,Math.Min(CloudDistance(input.Cloud,t.Cloud,start),CloudDistance(t.Cloud,input.Cloud,start)));double score=Math.Max(0,1-distance/.5-(input.Closed!=t.Closed?.06:0));if((input.StrokeCount==1&&t.StrokeCount==1&&!input.Closed&&!t.Closed)||(input.Linear&&t.Linear)){double an=Distance(input.Heading,new PointF()),bn=Distance(t.Heading,new PointF());if(an>.25&&bn>.25){double cosine=(input.Heading.X*t.Heading.X+input.Heading.Y*t.Heading.Y)/(an*bn);score=cosine<.2?0:Math.Max(0,score-(1-cosine)*.12);}}result.Add(new ShapeCandidate{Template=t,Score=score});}result.Sort((a,b)=>b.Score.CompareTo(a.Score));return result;}
 public static ShapeTemplate Match(Point[][] strokes,List<ShapeTemplate> templates,double threshold){var ranking=Rank(strokes,templates);return ranking.Count>0&&ranking[0].Score>=threshold?ranking[0].Template:null;}
}
